fill("deDE", {
	MBUFF_TXT_MISSING = "FEHLT",
	MBUFF_TXT_FORM = "GESTALT NUTZEN",
	MBUFF_TXT_SHIELD = "SCHILD",
	MBUFF_TXT_IMBUE = "WAFFENBUFF",
	MBUFF_TXT_STANCE = "HALTUNG NUTZEN",
	MBUFF_TXT_LETHAL = "TÖDLICHES GIFT",
	MBUFF_TXT_NONLETHAL = "NICHT TÖDLICH",
	MBUFF_TXT_PET = "BEGLEITER RUFEN",
	MBUFF_TXT_PET_DEAD = "BEGLEITER BELEBEN",
	MBUFF_TXT_ALLY = "VERBÜNDETEN BUFFEN",
	MBUFF_TXT_AURA = "AURA NUTZEN",
	MBUFF_TIP_HINT = "Klick zum Wirken (außerhalb des Kampfes) · Umschalt+Scrollen zum Skalieren · ziehen zum Bewegen",
	OPEN_TIP_HINT = "Linksklick: öffnen · Rechts-Ziehen: bewegen · Pfeil: Liste umschalten · Umschalt+Scrollen: skalieren",
	OPEN_TIP_CAPPED = "Saisonsumme erreicht, das öffnet sich also nicht. Ausgeben hilft nicht — die Grenze zählt, was du verdient hast. Sie steigt beim wöchentlichen Reset.",
	HOME_ROUTINE_SCOPE_NOTE = "Das ist die Woche DIESES Charakters. Delver's Call, Catalyst-Ladungen, Coffer Keys und Omnium Folio deiner anderen Charaktere stehen in der Account snapshot — klicke, um sie zu öffnen.",
	ACCOUNT_WEEKLY_SCOPE_NOTE = "Diese Liste gilt accountweit. Die wöchentlichen Questgeber in Silbermond, der Weltboss und die Void-Angriffe stehen auf This Week — klicke, um es zu öffnen.",
	DELVE_VALEERA_HEAL_TIP = "Blood-Stained Blades ist aktiv: heile Valeera weiter. Jede Heilung auf sie lässt sie für ein paar Sekunden härter zuschlagen, und das stapelt sich.",
	PROFCOURSE_CH_HIDDEN_FMT = "Du hast das Kapitel \"%s\" angefragt, und dieser Charakter hat diesen Beruf nicht — der Kurs kann es also nicht zeigen. Erlerne den Beruf, und das Kapitel erscheint hier. Solange siehst du dein nächstes offenes Kapitel.",
	DELVE_TIP_UNMEASURED = "Neu in Patch 12.1, auf der Gewundenen Insel. Midnight Helper hat diesen Delve auf deinem eigenen Client gefunden, aber noch niemand ist ihn gelaufen — deshalb steht hier keine Route, keine Trash-Liste und kein Bossplan statt eines geliehenen. Er füllt sich, sobald er gelaufen wurde. Läufst du ihn? /mh report packt in einen Textblock, was dir begegnet ist.",
	DELVE_REWARDS_UNMEASURED = "Saison 2 hat diese Gegenstandsstufen geändert, und Midnight Helper hat die neuen noch nicht gemessen. Statt dir Saison-1-Zahlen zu zeigen, die jetzt zu niedrig sind, bleibt diese Liste leer, bis ein echter Durchlauf sie füllt. Deine Endtruhe und deine Große Schatzkammer sind die ehrliche Antwort. Schon einen Durchlauf gemacht? /mh report macht daraus einen Block zum Einfügen.",
	WAY_SET_HERE = "Wegpunkt gesetzt: %s.",
	WAY_SET_ELSEWHERE = "Wegpunkt gesetzt: %s, in %s. Du bist in %s — reise erst dorthin, dann übernimmt der Pfeil.",
	WAY_NO_PIN = "Diese Karte akzeptiert ohne TomTom keinen Wegpunkt, also gibt es keinen Pfeil für %s in %s. Die Koordinaten im Text stimmen trotzdem.",
	WAY_FLIGHT_HINT = "Nächster Flugpunkt dort: %s.",
	DELVE_TIP_GNARLDOR_OVERVIEW = "• Neu in 12.1, auf der Gewundenen Insel — Eingang bei {WAY:2512:64.3:77.7:Gnarldor Isle}. Scrollmaster Ruma steht am Eingang. Ihre Quest It's a Satchel, Not a Bag schickt dich einmal hinein, für ihre Tasche: {WAY:2635:25.40:34.73:Ruma's Satchel}.|n• Drei Geschichten, zwei Bosse. Olds and Ends und Speaking Their Language enden bei Gralka Snake-Eater. Minchi's Osseous Adventure endet bei Osseous Amalgamation.|n• Klick die Tortollan Scrolls am Weg — Buffs, manche mit Haken.",
	DELVE_TIP_GNARLDOR_ROUTE = "• Drei Robuste Truhen — klick für einen Wegpunkt: {WAY:2635:60.44:68.12:Sturdy Chest 1} · {WAY:2635:52.41:40.84:Sturdy Chest 2} · {WAY:2635:28.67:41.69:Sturdy Chest 3}.|n• Du kommst bei etwa 77, 46 an; das Ausgangsportal steht genau dort — lauf die Truhen ab und du endest, wo du begonnen hast.|n• Olds and Ends: Sprich mit Tormunda, rette dann 8 Tortollan-Älteste und sammel ihre Relikte ein. Relikte droppen von Gnarldin, liegen auf dem Boden und stecken in Taschen – plünder also jede Tasche, an der du vorbeikommst.|n• Speaking Their Language: Sprich mit Artolla, befrei 3 Schildkröten und nimm die Schiffsvorräte auf: Pulver, Kanonenkugeln und Drehbassen. Die gelben Markierungen auf der Minikarte führen dich hin.|n• Speaking Their Language: Reite dann eine War Turtle und töte 50 Gnarldin. Gegen Gralka Snake-Eater kämpfst du zu Fuß; die Schildkröte kommt nicht mit.|n• Minchi's Osseous Adventure: Klick 4 Knochenhaufen an. Jeder ruft Gegnerwellen herbei, also heil dich vorher hoch. Es gibt mehr Haufen, als du brauchst.|n• Minchi's Osseous Adventure: Nimm 6 Gnarldin Hearts von Gnarldin-Leichen und geh dann zur Brücke, zum Ritual von Minchi. Dort erscheint der Boss.",
	DELVE_TIP_GNARLDOR_TRASH = "• Stonerender Raider: Sein Ansturm betäubt dich für 2.5 Sekunden. Danach kommt {SPELL:@muckwave}, ein 4 Sekunden langer Kegel. Tritt aus dem Bereich vor ihm.|n• Tuskcrusher Outrider: Stampede trifft hart und stößt dich weg. Kämpf dort, wo dich der Rückstoß nicht in eine andere Gruppe werfen kann.|n• Earthcaller Shaman: Unterbrich Mud Bolt.",
	DELVE_TIP_GNARLDOR_BOSS = "• Gralka Snake-Eater: {SPELL:@snake_eater}: Sie frisst zwei Schlangen, und Gift spritzt auf den Boden. Zieh sie da heraus. Jede Schlange lässt sie 15% mehr Schaden nehmen.|n• Gralka Snake-Eater: {SPELL:@venomblade_slash} vergiftet ihr Ziel. Es tut mehr weh für jede Schlange, die sie gefressen hat. Heil den Schaden weg.|n• Gralka Snake-Eater: {SPELL:@purging_breath} ist ein 6 Sekunden langer Kanalzauber: Alle 2 Sekunden atmet sie auf ihr Ziel. Weich jeder Welle seitlich aus.|n• Gralka Snake-Eater: Unterbrich Purging Breath nicht. Lass es laufen und weich weiter aus; eine Welle kann dich mit einem Treffer töten.|n• Gralka Snake-Eater: Stell Valeera für diesen Kampf auf Heiler. Auf DPS unterbricht sie, und dann unterbricht sie auch Purging Breath.|n• Osseous Amalgamation: {SPELL:@bone_armor_osseous} ist ein 2 Sekunden langer Zauber, der ihm einen großen Schild gibt. Unterbrich ihn.|n• Osseous Amalgamation: {SPELL:@bonestorm_osseous} trifft 8 Sekunden lang alle im Umkreis von 8 Metern. Lauf raus und warte, bis es vorbei ist.|n• Osseous Amalgamation: {SPELL:@bone_spike_osseous} lässt Stacheln unter deinen Füßen hochschießen, und die betäuben. Bleib in Bewegung und tritt von den Markierungen herunter.|n• Osseous Amalgamation: {SPELL:@frost_strike_osseous} verlangsamt dich 6 Sekunden lang um 50%. Halt eine Bewegungsfähigkeit bereit, damit dich Bonestorm nicht erwischt.",
	ARROW_LEAVE_INSTANCE_FIRST = "(erst hier raus)",
	GEM_OPEN_SOCKET_FMT = "Sockelfenster öffnen (%s)",
	DELVE_TIP_RINGOFGLORY_DANGER = "• Der Fissuring Slam des Golems lässt sich nicht unterbrechen. Ein Kick bringt nichts — die Zauberleiste trägt den Schild.|n• Er landet unter dir, du kannst dem Treffer also nicht ausweichen. Stunne ihn oder nutz einen Defensivzauber. Lauf danach vom rissigen Boden: Er schadet weiter und verlangsamt dich um 30%.|n• Er taucht nur in den höheren Tiers auf, und nicht allein: auf Tier 11 waren es drei, die frei umherliefen. Man kann sie einzeln pullen — tu das. Zwei zusammen sind zwei Slams, die du nicht unterbrechen kannst.|n• Midnight Helper kann dich im Moment des Zaubers nicht warnen: seit 12.1 darf ein Addon nicht mehr sehen, welchen Zauber ein Gegner wirkt. Deshalb steht es hier.",
	DELVE_TIP_RINGOFGLORY_OVERVIEW = "• Neu in 12.1, auf der Gewundenen Insel — Eingang bei {WAY:2512:71.1:56.4:The Ring of Glory}. Drei Geschichten: Open Night und Game Day enden bei Drakta, Adopt-a-thon endet bei Gnok.|n• Open Night ist die lange: Räum den Arenaboden und kämpf dann nacheinander gegen Champions: Crushfoot, die Bluegill Brothers, Brinebeater, Guth'kar the Bound, drei Arena Champions und zum Schluss Drakta.|n• |cffffffffCrushfoot|r stürmt, und dieser Ansturm ist es, der tötet. |cffffffffCrowd Control stoppt ihn|r — ein Stun oder ein Rückstoß, im Spiel bestätigt. Spieler berichten außerdem von zwei Türmen mit blau leuchtenden Kugeln, die dich hinüberteleportieren; das haben wir selbst nicht getestet.",
	DELVE_TIP_RINGOFGLORY_ROUTE = "• Drei Robuste Truhen — klick für einen Wegpunkt: {WAY:2633:44.16:22.60:Robuste Truhe 1} · {WAY:2633:25.19:73.74:Robuste Truhe 2} · {WAY:2633:48.56:94.84:Robuste Truhe 3}.|n• Der Ausgang liegt bei {WAY:2633:80.10:53.69:Ausgang}.|n• Open Night: Räum den Arenaboden 4 Mal. Auf hohen Tiers sind einige dieser Gegner Nemesis-Mobs, also pull vorsichtig.|n• Open Night: Töte in der Runde der Bluegill Brothers zuerst die zwei kleinen Zauberwirker und unterbrich sie.|n• Open Night: Unterbrich Tidal Rage von Brinebeater und verlass die Kreise von Break Water, bevor sie dich hochschleudern.|n• Open Night: Unterbrich Curse of Dread von Guth'kar the Bound. Konzentrier dich in der Champions-Runde auf Hexspitter Zit'ka und unterbrich sie.|n• Game Day: Spiel Headball. Schädel liegen herum und droppen von Gegnern; klick einen an, um ihn etwa 25 Meter nach vorn zu kicken. Erziel 8 Tore in den vier großen Obelisken.|n• Game Day: Nach jedem Tor kreisen fliegende Masken um diesen Obelisken und blocken deine Schüsse. Zwei Tore an jedem der vier Obelisken sind der einfache Weg zu 8.|n• Adopt-a-thon: Rette 8 Tierbabys und füll die Leiste, indem du Gegner tötest. Die Tiere laufen vor dir weg: Treib sie in eine Ecke oder nutz die Snacks, die herumliegen.|n• Adopt-a-thon: Jagst du einem Tier nach, pullst du leicht eine zusätzliche Gruppe. Schau, wohin es läuft, bevor du folgst.",
	DELVE_TIP_RINGOFGLORY_TRASH = "• Restless Spiritcaller: Unterbrich Soul Siphon, es heilt den Zaubernden. Tritt aus der Linie der Stacheln von {SPELL:@soul_impale}.|n• Arisen Warsinger: Töte die War Drum, die er aufstellt. Die Trommel gibt Gegnern in der Nähe 20% Tempo und bleibt, auch wenn der Warsinger stirbt.|n• Stonesoul Specter: {SPELL:@whirling_spirit} trifft alle im Umkreis von 10 Metern und lässt dich 30 Sekunden lang 50% mehr Schattenschaden nehmen. Geh während des 3 Sekunden langen Zaubers weg.|n• Überall Bodenfallen: {SPELL:@hex_pile} verwandelt dich bis zu einer Minute lang in einen Frosch (Schaden bricht es), und {SPELL:@thrusting_spear} verlangsamt dich um 33%. Schau, wohin du trittst.",
	DELVE_TIP_RINGOFGLORY_BOSS = "• Drakta: {SPELL:@soul_cleave_drakta} ist ein 3 Sekunden langer Zauber, der alle im Umkreis von 15 Metern trifft und einen {SPELL:@spirit_tear} hinterlässt. Geh raus und zieh ihn dann davon weg.|n• Drakta: {SPELL:@roar_of_the_champion} lässt ihn 50% härter zuschlagen, macht ihn aber 80% langsamer. Bleib außer Reichweite, bis es abklingt.|n• Drakta: Er zieht sein am weitesten entferntes Ziel zu sich. Eine Säule zwischen euch kann das blocken. Erreichst du keine rechtzeitig, halt einen Defensivzauber bereit.|n• Gnok: {SPELL:@upheaval_gnok} ist ein 4 Sekunden langer Zauber. Er springt auf sein Ziel und hinterlässt {SPELL:@ruptured_ground_gnok}. Geh raus, sobald er gelandet ist.|n• Gnok: Wenn er stirbt, steht er als untoter Affe mit vollem Leben wieder auf. Du tötest ihn zweimal.|n• Gnok: Untot wirkt er {SPELL:@necrotic_upheaval_gnok}, eine Linie von Eruptionen vor ihm. Sie verwandelt alten Ruptured Ground in {SPELL:@necrotic_ground_gnok}. Weich seitlich aus und bleib von alten Pfützen weg.|n• Gnok: {SPELL:@ejecting_decay} wirft verrottende Brocken herum. Jeder trifft eine kleine Stelle, also schau auf den Boden und tritt in die Lücken.",
	MARK_DRAG = "Ziehen zum Bewegen (außerhalb des Kampfes)",
	MARK_CLEAR_TARGET = "Zielmarkierung entfernen",
	MARK_CLEAR_WORLD = "Alle Weltmarkierungen entfernen",
	MARK_READYCHECK = "Bereitschaftsprüfung",
	MARK_ROLECHECK = "Rollenprüfung",
	MARK_COUNTDOWN = "Pull-Timer",
	MARK_COUNTDOWN_HINT = "Linksklick: %d Sekunden · Rechtsklick: abbrechen",
	MARK_NEEDLEAD = "Nur die Gruppenleitung oder ein Assistent kann das.",
	SET_MBUFF_TITLE = "Erinnerung an fehlende Buffs",
	SET_MBUFF_DESC = "Zeigt ein bewegliches Symbol, wenn du einen Klassenbuff wirken kannst, der nicht aktiv ist (Schlachtzugsbuff, Gestalt, Schild, Waffenbuff, Gift, Haltung, Begleiter). Klick es an, um zu wirken (außerhalb des Kampfes).",
	SET_MBUFF_TOGGLE_TITLE = "Symbol für fehlende Buffs anzeigen",
	SET_MBUFF_TOGGLE_DESC = "Zeigt die Erinnerung, sobald ein aufrechterhaltbarer Klassenbuff fehlt. Ziehen zum Bewegen, Umschalt+Scrollen zum Skalieren.",
	SET_OPEN_TITLE = "Öffenbares",
	SET_OPEN_DESC = "Zeigt einen beweglichen Button (mit Anzahl + Liste) für öffenbare Taschengegenstände — Horte, Schatztruhen, Beutel, Questbehälter. Klick zum Öffnen.",
	SET_OPEN_TOGGLE_TITLE = "Button für Öffenbares anzeigen",
	SET_OPEN_TOGGLE_DESC = "Zeigt den Button, sobald du öffenbare Gegenstände trägst. Linksklick öffnet, Rechts-Ziehen bewegt, Pfeil schaltet die Liste um.",
	SET_MARK_TITLE = "Schnellmarkierung",
	SET_MARK_DESC = "Zeigt eine bewegliche Leiste, um dein Ziel schnell zu markieren (Totenkopf, Kreuz, …) und Weltmarkierungen auf dem Boden zu setzen.",
	SET_MARK_TOGGLE_TITLE = "Schnellmarkierungs-Leiste anzeigen",
	SET_MARK_TOGGLE_DESC = "Erscheint nur, während du in einer Gruppe/einem Schlachtzug bist. Obere Reihe markiert dein Ziel + Bereitschaftsprüfung, untere Reihe setzt Weltmarkierungen (Linksklick setzen, Rechtsklick entfernen). Zieh den goldenen Griff zum Bewegen.",
})

