	GROUP_NOTE_LOH = "letzte Rettung, lange Abklingzeit; wirkt nicht auf jemanden, der in den letzten 30 Sekunden Divine Shield, Blessing of Protection oder Blessing of Spellwarding bekommen hat (Forbearance). Für dich selbst: Gesundheit schon niedrig, dann dies; kommt ein Treffer, den du nicht überlebst, dann Divine Shield kurz davor. Wähl eins",
	GROUP_NOTE_MASS_INVISIBILITY = "nur außerhalb eines Kampfes: die ganze Gruppe wird unsichtbar, um an Gegnern vorbeizuschleichen; jede Aktion beendet es",
	GROUP_NOTE_MASTER_S_CALL = "nur mit einem Cunning-Begleiter (den Typ wählst du beim Stable Master); wirkt auch auf dich",
	GROUP_NOTE_MISDIRECTION = "gibt deine Bedrohung an den Tank: drück es beim Pull auf den Tank, dann bleiben die Gegner beim Tank",
	GROUP_NOTE_NATURE_S_SWIFTNESS = "danach Regrowth auf die Person: kommt sofort an und heilt extra",
	GROUP_NOTE_OOC = "nur nach dem Kampf",
	GROUP_NOTE_POWER_INFUSION = "gib es einem Schadensmacher, wenn er seine große Abklingzeit drückt",
	GROUP_NOTE_POWER_INFUSION_2 = "meistens benutzt du es selbst in deinem Burst; mit Twins of the Sun Priestess gibst du es einem Schadensmacher und bekommst es auch",
	GROUP_NOTE_POWER_WORD_BARRIER = "leg sie auf den Boden unter die Gruppe (nur wenn du sie statt Ultimate Penitence gewählt hast)",
	GROUP_NOTE_PRIMAL_RAGE = "nur mit einem Ferocity-Begleiter; alle sind 40 Sek. schneller, einmal pro 10 Minuten und kein anderer Bloodlust: sprich mit der Gruppe ab, wann",
	GROUP_NOTE_PROTECTION = "nur gegen körperlichen Schaden; nicht auf den Tank",
	GROUP_NOTE_RAISE_ALLY = "wirkt im Kampf, kostet 30 Runenmacht; im Schlachtzug lieber einen Nicht-Tank machen lassen, wenn er kann",
	GROUP_NOTE_RAISE_ALLY_2 = "wirkt im Kampf, kostet 30 Runenmacht",
	GROUP_NOTE_RALLYING_CRY = "drück es kurz vor einem harten Treffer auf die ganze Gruppe",
	GROUP_NOTE_REAWAKEN = "nur nach dem Kampf; holt alle auf einmal zurück",
	GROUP_NOTE_REBIRTH = "wirkt im Kampf; die ganze Gruppe teilt sich die Anzahl",
	GROUP_NOTE_REBIRTH_2 = "wirkt im Kampf (kostet Wut); die ganze Gruppe teilt sich die Anzahl",
	GROUP_NOTE_RESCUE = "du fliegst die Person zu der Stelle, auf die du zielst; Verlangsamungen gehen auch weg",
	GROUP_NOTE_RESTORAL = "wie Revival, aber Magie bleibt drauf; geht sogar, wenn du betäubt bist",
	GROUP_NOTE_REVIVAL = "entfernt auch Magie, Gift und Krankheit von allen",
	GROUP_NOTE_REWIND = "direkt nach einem harten Treffer auf die Gruppe, nicht davor",
	GROUP_NOTE_ROAR_OF_SACRIFICE = "dein Begleiter bekommt die Hälfte ihres Schadens: halte deinen Begleiter am Leben",
	GROUP_NOTE_ROAR_OF_SACRIFICE_2 = "eine kleine Hilfe: 15% weniger Schaden",
	GROUP_NOTE_SAC = "du bekommst einen Teil ihres Schadens: nur wenn du selbst gesund bist",
	GROUP_NOTE_SOULSTONE = "leg ihn vor dem Kampf auf den Healer, oder zauber ihn auf jemanden, der im Kampf gestorben ist",
	GROUP_NOTE_SOURCE_OF_MAGIC = "leg es vor dem Kampf auf einen Healer: es hält eine Stunde",
	GROUP_NOTE_SOURCE_OF_MAGIC_2 = "leg es vor dem Kampf auf den anderen Healer: es hält eine Stunde",
	GROUP_NOTE_SPATIAL_PARADOX = "du und ein Healer könnt kurz beim Laufen zaubern",
	GROUP_NOTE_SPELLWARD = "nur gegen Magie; gleiche Abklingzeit wie Blessing of Protection",
	GROUP_NOTE_SPIRIT_LINK_TOTEM = "hilft nur Leuten, die dicht beieinander stehen: es verteilt ihre Gesundheit gleich und sie bekommen etwas weniger Schaden",
	GROUP_NOTE_STAMPEDING_ROAR = "benutz es, wenn die Gruppe rennen muss; du wechselst dabei in Bärengestalt",
	GROUP_NOTE_STAMPEDING_ROAR_2 = "benutz es, wenn die Gruppe rennen muss",
	GROUP_NOTE_TIGER_S_LUST = "kurze Reichweite: geh zuerst nah an die Person heran",
	GROUP_NOTE_TIME_DILATION = "die Hälfte ihres Schadens kommt langsam statt auf einmal",
	GROUP_NOTE_TIME_SPIRAL = "alle in deiner Nähe dürfen ihren Bewegungszauber noch einmal benutzen, auch mit Abklingzeit",
	GROUP_NOTE_TIME_WARP = "alle sind 40 Sek. schneller; nur einmal pro 10 Minuten und es blockiert jeden anderen Bloodlust: sprich mit der Gruppe ab, wann",
	GROUP_NOTE_TRANQUILITY = "du stehst still, solange es heilt; heb es für großen Gruppenschaden auf",
	GROUP_NOTE_TREMOR_TOTEM = "nur gegen Furcht, Bezauberung und Schlaf, nicht gegen Festhalten oder Verlangsamen (Talent: manche Builds nehmen stattdessen Poison Cleansing Totem)",
	GROUP_NOTE_VAMPIRIC_EMBRACE = "kein Ziel nötig: 12 Sek. lang heilt dein Shadow-Schaden auch jemanden in deiner Nähe",
	GROUP_NOTE_WIND_RUSH_TOTEM = "alle, die hindurchlaufen, rennen ein paar Sekunden schneller (mit dem Talent Jet Stream entfernt es auch Verlangsamungen)",
	GROUP_NOTE_WOG_OTHER = "kostet die Heilige Kraft, die dein Schild braucht: nur wenn es gratis ist oder du übrig hast",
	GROUP_NOTE_WORD_OF_GLORY = "kostet Heilige Kraft, die dein Schaden braucht: nur im Notfall",
	GROUP_NOTE_YU_LON_THE_JADE_SERPEN = "ein Helfer heilt eine Weile mit; nicht gleichzeitig mit Revival",
	GROUP_NOTE_ZEPHYR = "nur gegen Schaden, der eine Fläche trifft; hilft den 4 Leuten, die dir am nächsten stehen",
	GROUP_STEP_BOOST = "macht jemand anderen eine Weile stärker",
	GROUP_STEP_FREE = "wenn jemand festsitzt: festgehalten, verlangsamt oder verängstigt",
