	GROUP_STEP_RAID = "hilft allen in deiner Nähe auf einmal",
	GROUP_STEP_REZ = "wenn jemand gestorben ist",
	GROUP_STEP_SAVE = "um jemand anderen zu schützen: leg es kurz vor einem harten Treffer auf die Person",
