	PLAYCARD_103_MISTAKE = "{SPELL:22568} drücken, bevor {SPELL:1079} auf dem Ziel ist. Deine Blutungen laufen aus und dein Schaden sinkt.",
	PLAYCARD_103_HERO1 = "Druide der Klaue: Verheeren leuchtet anstelle von {SPELL:22568} auf. Drück es bei 5 Combopunkten und 50 Energie.",
	PLAYCARD_103_HERO2 = "Wildpirscher: keine neuen Tasten. Spiel die Schritte oben.",
	PLAYCARD_104_IDEA = "Schlag mit {SPELL:33917} und {SPELL:77758} zu, um Wut zu bekommen, und gib sie für {SPELL:192081} aus: das ist deine Rüstung.",
	PLAYCARD_104_S1 = "Körperliche Treffer kommen: halte mindestens 1 {SPELL:192081} aktiv. Für große Treffer mehr davon stapeln.",
	PLAYCARD_104_S2 = "{SPELL:33917} und {SPELL:77758} auf Cooldown: sie geben Wut. Halte {SPELL:8921} auf dem Ziel.",
	PLAYCARD_104_S3 = "Vor einem großen Treffer oder wenn deine Gesundheit sinkt: {SPELL:22842}. {SPELL:22812} oft; {SPELL:61336} für die größten Treffer.",
	PLAYCARD_104_S4 = "Wut übrig und du bist sicher: {SPELL:6807}. Sonst nichts? {SPELL:213764}.",
	PLAYCARD_104_AOE = "Gleiche Tasten. Mehr Gegner schlagen dich, also halte mehr Stapel {SPELL:192081} aktiv.",
	PLAYCARD_104_MISTAKE = "Deine ganze Wut in {SPELL:6807} stecken. Dann bleibt nichts für {SPELL:192081}, wenn die Treffer kommen.",
	PLAYCARD_104_HERO1 = "Druide der Klaue: Verheeren leuchtet anstelle von {SPELL:6807} auf. Drück es, am besten über 60 Wut.",
	PLAYCARD_104_HERO2 = "Elunes Auserwählte: {SPELL:204066} auf Cooldown. Auffüllen mit {SPELL:8921} statt {SPELL:213764}.",
	PLAYCARD_105_IDEA = "Leg früh HoTs auf Leute und stopf dann die großen Löcher mit {SPELL:8936}.",
	PLAYCARD_105_S1 = "Halte {SPELL:33763} immer aktiv: auf dem Tank oder im Schlachtzug auf dir selbst. {SPELL:145205} unter die Gruppe.",
	PLAYCARD_105_S2 = "{SPELL:18562} auf Cooldown, dann {SPELL:774}: diese {SPELL:774} landet auf 3 Leuten.",
	PLAYCARD_105_S3 = "Jemand stirbt gleich: {SPELL:8936} geht immer. Mit {SPELL:132158} vorher (wenn bereit) ist er sofort und kostenlos.",
	PLAYCARD_105_S4 = "Niemand braucht Heilung? {SPELL:5176} auf den Gegner.",
	PLAYCARD_105_AOE = "Vor Gruppenschaden: {SPELL:774} auf 5 Leute. Dann {SPELL:48438} und {SPELL:8936}, das jetzt billig ist. Riesiger Schaden: {SPELL:740}.",
	PLAYCARD_105_MISTAKE = "{SPELL:8936} zu deiner normalen Heilung machen, ohne dass 5 {SPELL:774} verteilt sind. Dann kostet er viel Mana. Mit 5 verteilt ist er 60 % billiger.",
	PLAYCARD_105_HERO1 = "Wildpirscher (am besten diese Saison): keine neue Taste. {SPELL:18562} hinterlässt eine Blume: dieses Ziel bekommt mehr Heilung.",
	PLAYCARD_105_HERO2 = "Hüter des Hains: keine neue Taste. Kleine Baumhelfer kommen und heilen mit dir.",
	PLAYCARD_250_IDEA = "Heil dich mit {SPELL:49998} und halte {SPELL:195181} mit {SPELL:195182} aktiv: das ist deine Rüstung.",
	PLAYCARD_250_S1 = "Gerade einen großen Treffer kassiert oder Runenmacht über 70? {SPELL:49998}.",
	PLAYCARD_250_S2 = "Weniger als 5 Aufladungen {SPELL:195181}? {SPELL:195182}. Nie auslaufen lassen.",
	PLAYCARD_250_S3 = "{SPELL:49028}, sobald bereit. Steh in {SPELL:43265}; neu legen, sobald der Effekt endet.",
	PLAYCARD_250_S4 = "{SPELL:50842}, bevor alle Aufladungen voll sind. Nichts anderes bereit? {SPELL:206930}.",
	PLAYCARD_250_AOE = "{SPELL:50842} öfter: es trifft jeden Gegner um dich herum. Halte {SPELL:43265} unter der Gruppe.",
	PLAYCARD_250_MISTAKE = "{SPELL:49998} bei voller Gesundheit. Er heilt für den Schaden der letzten 5 Sekunden, also drück ihn nach einem Treffer.",
	PLAYCARD_250_HERO1 = "San'layn (am besten diese Saison): Während {SPELL:49028} einmal {SPELL:50842}, dann nur noch {SPELL:433895} und {SPELL:49998}.",
	PLAYCARD_250_HERO2 = "Todesbringer: Erst {SPELL:439843}, dann {SPELL:49028}. Leuchtet {SPELL:195182} auf, nutze ihn, bevor er ausläuft.",
	PLAYCARD_251_IDEA = "Gib Runen für {SPELL:49020} aus, Runenmacht für {SPELL:49143}, und schnapp dir die Gratis-Treffer, wenn sie aufleuchten.",
	PLAYCARD_251_S1 = "{SPELL:51271}, sobald bereit, dann {SPELL:279302}: dein großer Moment. {SPELL:152279} gehört dazu, falls geskillt.",
	PLAYCARD_251_S2 = "{SPELL:49020}, wenn Tötungsmaschine es aufleuchten lässt. {SPELL:49184} nur, wenn Raureif sie aufleuchten lässt.",
	PLAYCARD_251_S3 = "Gib Runenmacht für {SPELL:49143} aus. Keine Runenmacht mehr? {SPELL:47568}.",
	PLAYCARD_251_S4 = "Nichts anderes bereit? Ein normales {SPELL:49020}.",
	PLAYCARD_251_AOE = "3 oder mehr Gegner: {SPELL:207230} statt {SPELL:49020} und {SPELL:194913} statt {SPELL:49143}.",
	PLAYCARD_251_MISTAKE = "{SPELL:49184} ohne Raureif. Ohne das Aufleuchten ist sie zu schwach, um eine Rune wert zu sein.",
	PLAYCARD_251_HERO1 = "Todesbringer: {SPELL:439843} direkt vor {SPELL:51271}. Es gibt extra Tötungsmaschinen, die du währenddessen ausgeben kannst.",
	PLAYCARD_251_HERO2 = "Reiter der Apokalypse: keine Extra-Taste. Die Reiter kommen von selbst; spiel einfach die Schritte oben.",
	PLAYCARD_252_IDEA = "Bau Niedere Ghule mit {SPELL:85948} auf, nutze sie mit {SPELL:55090} und gib Runenmacht für {SPELL:47541} aus.",
	PLAYCARD_252_S1 = "{SPELL:42650} und {SPELL:1233448} zusammen, sobald bereit: dein großer Moment.",
	PLAYCARD_252_S2 = "Halte deine Seuche mit {SPELL:77575} auf dem Ziel. Während {SPELL:1233448} läuft, drück {SPELL:1247378}.",
	PLAYCARD_252_S3 = "{SPELL:47541}, wenn er aufleuchtet. Schwärende Sense (kommt nach {SPELL:85948}), wenn ihr Buff auf dir fast weg ist.",
	PLAYCARD_252_S4 = "Keine Niederen Ghule? {SPELL:85948}. Welche da? {SPELL:55090}.",
	PLAYCARD_252_S5 = "Nichts anderes bereit? {SPELL:47541}.",
	PLAYCARD_252_AOE = "Leg {SPELL:43265} unter die Gruppe. 3 oder mehr Gegner: {SPELL:207317} statt {SPELL:47541}.",
	PLAYCARD_252_MISTAKE = "Deine Seuche vom Ziel fallen lassen: keine Seuche heißt weniger billige, starke {SPELL:47541}.",
	PLAYCARD_252_HERO1 = "Reiter der Apokalypse: keine Extra-Taste. Die Reiter kommen von selbst; spiel einfach die Schritte oben.",
	PLAYCARD_252_HERO2 = "San'layn: Während {SPELL:1233448} wird {SPELL:55090} zu {SPELL:433895}. Drück ihn oft, damit sein Buff aktiv bleibt.",
	PLAYCARD_253_IDEA = "Deine Tiere erledigen die harte Arbeit: Du schickst sie los und hältst sie wütend.",
	PLAYCARD_253_S1 = "{SPELL:19574} jedes Mal, wenn bereit, etwa alle 30 Sekunden. Schieß kurz davor einen {SPELL:217200}.",
	PLAYCARD_253_S2 = "{SPELL:34026}, sobald bereit. Setz einen anderen Schuss zwischen zwei Tötungsbefehle.",
	PLAYCARD_253_S3 = "{SPELL:217200}, bevor er 2 Aufladungen erreicht: die Blutung wächst und er gibt Fokus.",
	PLAYCARD_253_S4 = "Nichts anderes bereit? {SPELL:193455}. Er bringt auch {SPELL:34026} früher zurück.",
	PLAYCARD_253_AOE = "{SPELL:1264359}, sobald bereit, und direkt nach {SPELL:19574}: dann treffen deine Tiere jeden Gegner.",
	PLAYCARD_253_MISTAKE = "{SPELL:217200} oder {SPELL:34026} bei 2 Aufladungen liegen lassen: das ist verschenkter Gratis-Schaden.",
	PLAYCARD_253_HERO1 = "Rudelführer (am besten diese Saison): Nach {SPELL:19574} ruft {SPELL:34026} ein Wildtier und eine Stampede. Richte diese Linie durch die Gruppe aus.",
	PLAYCARD_253_HERO2 = "Dunkler Waldläufer: {SPELL:466930}, wann immer möglich, in den ersten 10 Sekunden von {SPELL:19574}; beende dieses Fenster mit {SPELL:392060}.",
	PLAYCARD_254_IDEA = "Schieß aus der Ferne: {SPELL:19434} macht deinen nächsten Schuss stärker, und den gibst du für {SPELL:185358} aus.",
	PLAYCARD_254_S1 = "{SPELL:212431} zweimal hintereinander und {SPELL:260243}, sobald sie bereit sind.",
	PLAYCARD_254_S2 = "{SPELL:288613}, sobald bereit: dein großer Moment, etwa alle 2 Minuten.",
	PLAYCARD_254_S3 = "{SPELL:257044}, sobald bereit. Dann {SPELL:19434}; nie bei 2 Aufladungen liegen lassen.",
	PLAYCARD_254_S4 = "Hat {SPELL:19434} deinen nächsten Schuss aufleuchten lassen? Gib ihn für {SPELL:185358} aus, vor dem nächsten Gezielten Schuss.",
	PLAYCARD_254_S5 = "Nichts anderes bereit? {SPELL:56641}. Schieß weiter, auch in Bewegung.",
	PLAYCARD_254_AOE = "{SPELL:2643} statt {SPELL:185358}. Bei 3 oder mehr Gegnern treffen dann dein nächster {SPELL:19434} und {SPELL:257044} alle.",
	PLAYCARD_254_MISTAKE = "{SPELL:19434} bei 2 Aufladungen liegen lassen: dieser große Pfeil ist für immer weg.",
	PLAYCARD_254_HERO1 = "Schildwache (am besten diese Saison): Wirf Mondscheinchakram gegen Ende von {SPELL:288613}, wenn noch etwa 5 Sekunden übrig sind.",
	PLAYCARD_254_HERO2 = "Dunkler Waldläufer: Gib den aufleuchtenden Schuss stattdessen für {SPELL:466930} aus. {SPELL:288613} wird dann zu {SPELL:392060}: einmal drücken.",
	PLAYCARD_255_IDEA = "Kämpf nah dran mit deinem Tier: Jeder {SPELL:259489} macht deine nächsten 2 Angriffe stärker.",
	PLAYCARD_255_S1 = "{SPELL:1250646}, sobald bereit: dein großer Moment. Drück kurz davor {SPELL:259489}.",
	PLAYCARD_255_S2 = "Die Schleife: {SPELL:259489}, dann zwei andere Angriffe, dann wieder {SPELL:259489}.",
	PLAYCARD_255_S3 = "{SPELL:259495} und {SPELL:1261193}, sobald bereit. Lass {SPELL:259495} nie bei 2 Aufladungen liegen.",
	PLAYCARD_255_S4 = "Gib deinen restlichen Fokus für {SPELL:186270} aus. Jeder zweite wird zu Raptorhieb.",
