	PLAYCARD_256_MISTAKE = "Gegner treffen, während niemand {SPELL:81749} hat: Dann heilt dein Schaden niemanden.",
	PLAYCARD_256_HERO1 = "Leerenweber (am besten in Schlachtzügen): {SPELL:8092} öffnet einen Riss. Steh still und wirk {SPELL:450215}, solange er offen ist.",
	PLAYCARD_256_HERO2 = "Orakel (am besten in Dungeons): {SPELL:47540} bekommt eine zweite Aufladung. Wirk {SPELL:17} direkt nach jeder {SPELL:47540}.",
	PLAYCARD_257_IDEA = "Heil mit deinen Segensworten. Jede normale Heilung, die du wirkst, bringt sie früher zurück.",
