	PLAYCARD_251_HERO2 = "Cavaliere dell'Apocalisse: nessun tasto in più. I cavalieri arrivano da soli; segui i passi qui sopra.",
	PLAYCARD_252_IDEA = "Crea Ghoul Minori con {SPELL:85948}, usali con {SPELL:55090} e spendi Potenza Runica in {SPELL:47541}.",
	PLAYCARD_252_S1 = "{SPELL:42650} e {SPELL:1233448} insieme quando sono pronti: il tuo momento forte.",
	PLAYCARD_252_S2 = "Tieni la tua malattia sul bersaglio con {SPELL:77575}. Mentre {SPELL:1233448} è attivo, premi {SPELL:1247378}.",
