	PLAYCARD_252_S4 = "Niente Ghoul Minori? {SPELL:85948}. Ne hai? {SPELL:55090}.",
	PLAYCARD_252_S5 = "Nient'altro di pronto? {SPELL:47541}.",
	PLAYCARD_252_AOE = "Metti {SPELL:43265} sotto il gruppo di nemici. 3 o più nemici: {SPELL:207317} invece di {SPELL:47541}.",
	PLAYCARD_252_MISTAKE = "Lasciar scadere la malattia sul bersaglio: senza malattia hai meno {SPELL:47541} economici e potenti.",
	PLAYCARD_252_HERO1 = "Cavaliere dell'Apocalisse: nessun tasto in più. I cavalieri arrivano da soli; segui i passi qui sopra.",
	PLAYCARD_252_HERO2 = "San'layn: durante {SPELL:1233448}, {SPELL:55090} diventa {SPELL:433895}. Premilo spesso per mantenere attivo il suo potenziamento.",
	PLAYCARD_253_IDEA = "I tuoi famigli fanno il lavoro duro: tu li mandi all'attacco e li tieni arrabbiati.",
	PLAYCARD_253_S1 = "{SPELL:19574} ogni volta che è pronto, circa ogni 30 secondi. Spara {SPELL:217200} subito prima.",
	PLAYCARD_253_S2 = "{SPELL:34026} ogni volta che è pronto. Metti un altro colpo tra due Ordini di Morte.",
	PLAYCARD_253_S3 = "{SPELL:217200} prima che arrivi a 2 cariche: il sanguinamento cresce e dà Focus.",
	PLAYCARD_253_S4 = "Nient'altro di pronto? {SPELL:193455}. Fa anche tornare prima {SPELL:34026}.",
	PLAYCARD_253_AOE = "{SPELL:1264359} ogni volta che è pronto, e subito dopo {SPELL:19574}: così i tuoi famigli colpiscono ogni nemico.",
	PLAYCARD_253_MISTAKE = "Lasciare {SPELL:217200} o {SPELL:34026} fermi a 2 cariche: sono danni gratis buttati via.",
	PLAYCARD_253_HERO1 = "Capobranco (la scelta migliore in questa stagione): dopo {SPELL:19574}, {SPELL:34026} chiama una bestia e un Impeto. Mira quella linea attraverso il gruppo di nemici.",
	PLAYCARD_253_HERO2 = "Guardaboschi Oscuro: {SPELL:466930} ogni volta che puoi nei primi 10 secondi di {SPELL:19574}; chiudi quel momento con {SPELL:392060}.",
	PLAYCARD_254_IDEA = "Tira da lontano: {SPELL:19434} rende più forte il tuo prossimo tiro, e lo spendi in {SPELL:185358}.",
	PLAYCARD_254_S1 = "{SPELL:212431} due volte di fila, e {SPELL:260243}, ogni volta che sono pronti.",
	PLAYCARD_254_S2 = "{SPELL:288613} quando è pronto: il tuo momento forte, circa ogni 2 minuti.",
	PLAYCARD_254_S3 = "{SPELL:257044} ogni volta che è pronto. Poi {SPELL:19434}; non lasciarlo mai fermo a 2 cariche.",
