	PLAYCARD_255_HERO2 = "Capobranco: quando si illumina Ululato del Capobranco, {SPELL:259489} chiama una bestia. Durante {SPELL:1250646}, mira la linea dell'Impeto.",
	PLAYCARD_256_IDEA = "Curi facendo male ai nemici: ogni alleato con {SPELL:81749} viene curato dai tuoi danni.",
	PLAYCARD_256_S1 = "Tieni sempre {SPELL:589} sul nemico.",
	PLAYCARD_256_S2 = "{SPELL:17} su un alleato che sta per essere colpito: dà {SPELL:81749}. Quando si illumina {SPELL:1253593}, usa quello.",
	PLAYCARD_256_S3 = "{SPELL:8092} e {SPELL:47540} ogni volta che sono pronti: i tuoi colpi più forti, quindi le tue cure più grandi.",
	PLAYCARD_256_S4 = "Nient'altro di pronto? {SPELL:585}. Qualcuno molto basso? {SPELL:186263} su di lui, o {SPELL:2061} se non hai preso quel talento.",
