	PLAYCARD_256_HERO2 = "Oracolo (la scelta migliore nei dungeon): {SPELL:47540} ottiene una seconda carica. Lancia {SPELL:17} subito dopo ogni {SPELL:47540}.",
	PLAYCARD_257_IDEA = "Cura con le tue Parole Sacre. Ogni cura normale che lanci le fa tornare prima.",
